sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    // Initialize GlideAjax calling our scoped Script Include
    var ga = new GlideAjax('OffboardingUtils');
    ga.addParam('sysparm_name', 'getEmployeeAssetSummary');
    ga.addParam('sysparm_user_id', newValue);

    ga.getXMLAnswer(function(response) {
        if (!response) {
            return;
        }

        try {
            var result = JSON.parse(response);
            if (result.success) {
                // Ensure field names match your schema
                var assetField = g_form.hasField('asset_count') ? 'asset_count' : 'u_asset_count';
                var targetField = g_form.hasField('target_employee') ? 'target_employee' : 'u_target_employee';

                g_form.setValue(assetField, result.assetCount);

                if (result.assetCount > 0) {
                    g_form.showFieldMsg(targetField, 'Found ' + result.assetCount + ' assigned active assets requiring retrieval.', 'info');
                } else {
                    g_form.showFieldMsg(targetField, 'No active hardware assets found for this user.', 'warning');
                }
            }
        } catch (e) {
            console.error('[ClientScript] Failed to parse asset summary response: ' + e);
        }
    });
}
